{
  "name": "@atlascloudai/opencode",
  "version": "1.0.3",
  "description": "OpenCode plugin for Atlas Cloud - Access 100+ AI models including GPT-4o, Claude, Gemini, DeepSeek via OpenAI-compatible API",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "bin": {
    "atlascloudai-opencode": "./bin/setup.cjs"
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "prepublishOnly": "npm run build",
    "test": "echo \"No tests yet\" && exit 0"
  },
  "keywords": [
    "opencode",
    "plugin",
    "atlascloud",
    "atlas-cloud",
    "ai",
    "llm",
    "gpt-4",
    "claude",
    "gemini",
    "deepseek",
    "openai-compatible"
  ],
  "author": "Atlas Cloud",
  "license": "MIT",
  "homepage": "https://github.com/AtlasCloudAI/opencode-plugin#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AtlasCloudAI/opencode-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/AtlasCloudAI/opencode-plugin/issues"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.85",
    "zod": "^3.22.4"
  },
  "devDependencies": {
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "files": [
    "dist",
    "bin",
    "README.md"
  ],
  "engines": {
    "node": ">=18.0.0"
  }
}
